// Filter overdue invoices
const invoices = $input.all();
const today = new Date();
const overdue = [];
const today_invoices = [];
const upcoming = [];

for (const inv of invoices) {
  const dueDate = new Date(inv.json.invoice_date_due);
  const daysDiff = Math.floor((today - dueDate) / (1000 * 60 * 60 * 24));

  if (daysDiff > 0) {
    overdue.push({
      name: inv.json.name,
      customer: inv.json.partner_id ? inv.json.partner_id[1] : 'Unknown',
      amount: inv.json.amount_residual,
      days_overdue: daysDiff,
      priority: daysDiff > 30 ? 'URGENT' : daysDiff > 7 ? 'HIGH' : 'MEDIUM'
    });
  } else if (daysDiff === 0) {
    today_invoices.push(inv.json);
  } else if (daysDiff >= -7) {
    upcoming.push(inv.json);
  }
}

return [
  { json: { type: 'overdue', items: overdue, count: overdue.length } },
  { json: { type: 'today', items: today_invoices, count: today_invoices.length } },
  { json: { type: 'upcoming', items: upcoming, count: upcoming.length } }
];

